### 최대 힙 C 구현

```c
#define MAX_ELEMENT 200

typedef struct { int key; } element;

typedef struct {
    element heap[MAX_ELEMENT];
    int heap_size;
} HeapType;

// 삽입 함수
void insert_max_heap(HeapType* h, element item) {
    int i = ++(h->heap_size);

    // 부모 노드와 비교하며 거슬러 올라감
    while (i != 1 && item.key > h->heap[i/2].key) {
        h->heap[i] = h->heap[i/2];  // 부모를 아래로 끌어내림
        i /= 2;
    }
    h->heap[i] = item;  // 최종 위치에 삽입
}

// 삭제 함수 (최댓값 반환)
element delete_max_heap(HeapType* h) {
    element item = h->heap[1];        // 루트(최댓값) 저장
    element temp = h->heap[h->heap_size--]; // 마지막 노드
    int parent = 1, child = 2;

    while (child <= h->heap_size) {
        // 두 자식 중 큰 것 선택
        if (child < h->heap_size &&
            h->heap[child].key < h->heap[child+1].key)
            child++;

        if (temp.key >= h->heap[child].key) break;

        h->heap[parent] = h->heap[child];  // 자식을 위로
        parent = child;
        child *= 2;
    }
    h->heap[parent] = temp;
    return item;
}
```

### 사용 예시

```c
// 삽입: 10, 5, 30
insert_max_heap(heap, (element){10});
insert_max_heap(heap, (element){5});
insert_max_heap(heap, (element){30});

// 삭제: 30, 10, 5 순서로 나옴
delete_max_heap(heap);  // 30
delete_max_heap(heap);  // 10
delete_max_heap(heap);  // 5
```

